# Minimal tracked-change + comment engine for WordprocessingML
import copy, re
from lxml import etree
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML_NS = "http://www.w3.org/XML/1998/namespace"
def w(tag): return "{%s}%s" % (W, tag)
AUTHOR = "Hartwell, Brannigan & Locke LLP (for GRS)"
DATE = "2024-09-30T09:00:00Z"
_id = [1000]
def nid():
    _id[0] += 1
    return str(_id[0])

class Doc:
    def __init__(self, path):
        self.path = path
        self.tree = etree.parse(path)
        self.body = self.tree.getroot().find(w("body"))
        self.comments = []  # (id, text)
        self.log = []
    def paras(self):
        return list(self.body.iter(w("p")))
    @staticmethod
    def ptext(p):
        return "".join(t.text or "" for r in p.findall(w("r")) for t in r.findall(w("t")))
    def find(self, needle, contains=True):
        hits = [p for p in self.paras() if (needle in self.ptext(p))]
        if len(hits) != 1:
            raise ValueError("find(%r) matched %d paragraphs" % (needle[:60], len(hits)))
        return hits[0]
    # split run r at char offset k -> (left,right), both in place
    @staticmethod
    def _split_run(r, k):
        t = r.find(w("t")); s = t.text or ""
        if k <= 0 or k >= len(s): return None
        r2 = copy.deepcopy(r)
        t.text = s[:k]; t.set("{%s}space" % XML_NS, "preserve")
        t2 = r2.find(w("t")); t2.text = s[k:]; t2.set("{%s}space" % XML_NS, "preserve")
        r.addnext(r2)
        return r2
    def _runs_with_offsets(self, p):
        out = []; pos = 0
        for r in p.findall(w("r")):
            ts = r.findall(w("t"))
            if len(ts) != 1:
                if ts: raise ValueError("multi-t run")
                continue
            s = ts[0].text or ""
            out.append((r, pos, pos + len(s))); pos += len(s)
        return out
    def _isolate(self, p, start, end):
        # ensure run boundaries at start and end; return runs covering [start,end)
        for k in (start, end):
            for r, a, b in self._runs_with_offsets(p):
                if a < k < b:
                    self._split_run(r, k - a); break
        return [r for r, a, b in self._runs_with_offsets(p) if a >= start and b <= end and b > a]
    def _mk_ins_run(self, text, rpr_src=None, bold=None, italic=None, underline=None):
        r = etree.Element(w("r"))
        if rpr_src is not None and rpr_src.find(w("rPr")) is not None:
            rpr = copy.deepcopy(rpr_src.find(w("rPr")))
        else:
            rpr = etree.fromstring("<w:rPr xmlns:w=\"%s\"><w:rFonts w:ascii=\"Times New Roman\" w:hAnsi=\"Times New Roman\"/><w:color w:val=\"000000\"/><w:sz w:val=\"22\"/></w:rPr>" % W)
        for flag, tag in ((bold, "b"), (italic, "i")):
            if flag is True and rpr.find(w(tag)) is None:
                el = etree.Element(w(tag)); 
                rf = rpr.find(w("rFonts")); (rf.addnext(el) if rf is not None else rpr.insert(0, el))
            if flag is False:
                for el in rpr.findall(w(tag)): rpr.remove(el)
        if underline is True and rpr.find(w("u")) is None:
            u = etree.SubElement(rpr, w("u")); u.set(w("val"), "single")
        if underline is False:
            for el in rpr.findall(w("u")): rpr.remove(el)
        r.append(rpr)
        t = etree.SubElement(r, w("t")); t.text = text; t.set("{%s}space" % XML_NS, "preserve")
        return r
    def _ins_wrap(self, runs):
        ins = etree.Element(w("ins")); ins.set(w("id"), nid()); ins.set(w("author"), AUTHOR); ins.set(w("date"), DATE)
        for r in runs: ins.append(r)
        return ins
    def _del_runs(self, runs):
        first = runs[0]
        d = etree.Element(w("del")); d.set(w("id"), nid()); d.set(w("author"), AUTHOR); d.set(w("date"), DATE)
        first.addprevious(d)
        for r in runs:
            t = r.find(w("t")); t.tag = w("delText"); t.set("{%s}space" % XML_NS, "preserve")
            d.append(r)
        return d
    def replace(self, needle_para, old, new, comment=None, fmt=None):
        p = self.find(needle_para)
        txt = self.ptext(p)
        n = txt.count(old)
        if n != 1: raise ValueError("replace: %r occurs %d times in para %r" % (old[:50], n, needle_para[:40]))
        start = txt.index(old); end = start + len(old)
        runs = self._isolate(p, start, end)
        src = runs[0]
        d = self._del_runs(runs)
        anchor = d
        if new:
            segs = new if isinstance(new, list) else [(new, {})]
            ins = self._ins_wrap([self._mk_ins_run(s, src, **f) for s, f in segs])
            d.addnext(ins); anchor = ins
        if comment: self._comment_around(p, d, anchor, comment)
        self.log.append(("replace", needle_para[:40], old[:40]))
        return p
    def insert_at(self, needle_para, after_text, new, comment=None, before=False):
        p = self.find(needle_para)
        txt = self.ptext(p)
        if after_text is None:
            k = len(txt) if not before else 0
        else:
            if txt.count(after_text) != 1: raise ValueError("insert_at: anchor %r count %d" % (after_text[:40], txt.count(after_text)))
            k = txt.index(after_text) + (0 if before else len(after_text))
        ro = self._runs_with_offsets(p)
        for r, a, b in ro:
            if a < k < b: self._split_run(r, k - a); break
        ro = self._runs_with_offsets(p)
        prev = [r for r, a, b in ro if b <= k and b > a]
        nxt = [r for r, a, b in ro if a >= k and b > a]
        src = prev[-1] if prev else (nxt[0] if nxt else None)
        segs = new if isinstance(new, list) else [(new, {})]
        ins = self._ins_wrap([self._mk_ins_run(s, src, **f) for s, f in segs])
        if prev: prev[-1].addnext(ins)
        elif nxt: nxt[0].addprevious(ins)
        else: p.append(ins)
        if comment: self._comment_around(p, ins, ins, comment)
        self.log.append(("insert", needle_para[:40]))
        return p
    def insert_para_after(self, ref, segs, comment=None, template=None, before=False):
        refp = self.find(ref) if isinstance(ref, str) else ref
        tp = self.find(template) if isinstance(template, str) else (template if template is not None else refp)
        newp = etree.Element(w("p"))
        ppr = tp.find(w("pPr"))
        ppr = copy.deepcopy(ppr) if ppr is not None else etree.Element(w("pPr"))
        for x in ppr.findall(w("rPr")): ppr.remove(x)
        rpr = etree.SubElement(ppr, w("rPr")); mark = etree.SubElement(rpr, w("ins"))
        mark.set(w("id"), nid()); mark.set(w("author"), AUTHOR); mark.set(w("date"), DATE)
        newp.append(ppr)
        src = [r for r in tp.findall(w("r")) if r.find(w("t")) is not None]
        plain = None
        for r in src:
            rp = r.find(w("rPr"))
            if rp is None or (rp.find(w("b")) is None and rp.find(w("i")) is None): plain = r; break
        if plain is None and src: plain = src[-1]
        segs = segs if isinstance(segs, list) else [(segs, {})]
        ins = self._ins_wrap([self._mk_ins_run(s, plain, **f) for s, f in segs])
        newp.append(ins)
        if before: refp.addprevious(newp)
        else: refp.addnext(newp)
        if comment: self._comment_around(newp, ins, ins, comment)
        return newp
    def comment_para(self, needle_para, comment, sub=None):
        p = self.find(needle_para)
        if sub:
            txt = self.ptext(p); assert txt.count(sub) == 1, sub
            s = txt.index(sub); runs = self._isolate(p, s, s + len(sub))
            self._comment_around(p, runs[0], runs[-1], comment)
        else:
            runs = [r for r in p.findall(w("r")) if r.find(w("t")) is not None]
            self._comment_around(p, runs[0], runs[-1], comment)
    def _comment_around(self, p, first_el, last_el, text):
        cid = str(len(self.comments))
        self.comments.append((cid, text))
        cs = etree.Element(w("commentRangeStart")); cs.set(w("id"), cid)
        ce = etree.Element(w("commentRangeEnd")); ce.set(w("id"), cid)
        first_el.addprevious(cs); last_el.addnext(ce)
        rr = etree.Element(w("r")); rpr = etree.SubElement(rr, w("rPr")); rs = etree.SubElement(rpr, w("rStyle")); rs.set(w("val"), "CommentReference")
        ref = etree.SubElement(rr, w("commentReference")); ref.set(w("id"), cid)
        ce.addnext(rr)
    def save(self, out):
        self.tree.write(out, xml_declaration=True, encoding="UTF-8", standalone=True)
    def comments_xml(self):
        root = etree.Element(w("comments"), nsmap={"w": W})
        for cid, text in self.comments:
            c = etree.SubElement(root, w("comment")); c.set(w("id"), cid); c.set(w("author"), AUTHOR); c.set(w("date"), DATE); c.set(w("initials"), "HBL")
            for i, para in enumerate(text.split("\n")):
                p = etree.SubElement(c, w("p"))
                ppr = etree.SubElement(p, w("pPr")); ps = etree.SubElement(ppr, w("pStyle")); ps.set(w("val"), "CommentText")
                if i == 0:
                    r0 = etree.SubElement(p, w("r")); rp = etree.SubElement(r0, w("rPr")); rs = etree.SubElement(rp, w("rStyle")); rs.set(w("val"), "CommentReference")
                    etree.SubElement(r0, w("annotationRef"))
                r = etree.SubElement(p, w("r")); t = etree.SubElement(r, w("t")); t.text = para; t.set("{%s}space" % XML_NS, "preserve")
        return etree.tostring(root, xml_declaration=True, encoding="UTF-8", standalone=True)
PYEOF
