from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
def T(s): return s.replace("`", "’")
doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1); sec.top_margin = sec.bottom_margin = Inches(1)
st = doc.styles["Normal"]; st.font.name = "Times New Roman"; st.font.size = Pt(11)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
for hn, sz in (("Heading 1", 13), ("Heading 2", 11.5), ("Heading 3", 11)):
    h = doc.styles[hn]; h.font.name = "Times New Roman"; h.font.size = Pt(sz); h.font.bold = True; h.font.color.rgb = RGBColor(0, 0, 0)
    h.element.rPr.rFonts.set(qn("w:asciiTheme"), "") if False else None
def _runs(p, text):
    # **bold** and _italic_ light markup
    import re
    parts = re.split(r"(\*\*[^*]+\*\*|__[^_]+__)", T(text))
    for part in parts:
        if part.startswith("**") and part.endswith("**"): r = p.add_run(part[2:-2]); r.bold = True
        elif part.startswith("__") and part.endswith("__"): r = p.add_run(part[2:-2]); r.italic = True
        elif part: p.add_run(part)
    return p
def H(text, lvl=1):
    p = doc.add_heading(T(text), level=lvl)
    for r in p.runs: r.font.name = "Times New Roman"; r.font.color.rgb = RGBColor(0,0,0)
    return p
def Pp(text, after=6, align=None, size=None):
    p = doc.add_paragraph(); _runs(p, text); p.paragraph_format.space_after = Pt(after)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    if align == "j": p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if size:
        for r in p.runs: r.font.size = Pt(size)
    return p
def Bl(text, lvl=0, num=False):
    p = doc.add_paragraph(style="List Number" if num else ("List Bullet" if lvl == 0 else "List Bullet 2"))
    _runs(p, text); p.paragraph_format.space_after = Pt(3); return p
def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr(); s = OxmlElement("w:shd"); s.set(qn("w:val"), "clear"); s.set(qn("w:color"), "auto"); s.set(qn("w:fill"), hexcolor); tcPr.append(s)
def Tab(headers, rows, widths=None, size=9, header_fill="D9D9D9"):
    t = doc.add_table(rows=1, cols=len(headers)); t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""; p = c.paragraphs[0]; r = p.add_run(T(h)); r.bold = True; r.font.size = Pt(size); shade(c, header_fill)
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""; p = cells[i].paragraphs[0]; _runs(p, str(v))
            for r in p.runs: r.font.size = Pt(size)
    # repeat header
    trPr = t.rows[0]._tr.get_or_add_trPr(); th = OxmlElement("w:tblHeader"); th.set(qn("w:val"), "true"); trPr.append(th)
    if widths:
        for row in t.rows:
            for i, wdt in enumerate(widths): row.cells[i].width = Inches(wdt)
    doc.add_paragraph().paragraph_format.space_after = Pt(2)
    return t
def header_footer(text_h, text_f):
    hp = sec.header.paragraphs[0]; hp.text = T(text_h); hp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    for r in hp.runs: r.font.size = Pt(8); r.bold = True
    fp = sec.footer.paragraphs[0]; fp.text = T(text_f); fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    for r in fp.runs: r.font.size = Pt(8)
PYEOF
